-- Optional SQL Server schema for a future SQL-backed repository.
-- The Stage 14 application continues to use local JSON; this script does not migrate data.
IF DB_ID(N'AshkanLMS') IS NULL CREATE DATABASE AshkanLMS;
GO
USE AshkanLMS;
GO
IF OBJECT_ID(N'dbo.Students',N'U') IS NULL
CREATE TABLE dbo.Students (Id INT NOT NULL PRIMARY KEY, Name NVARCHAR(120) NOT NULL, Email NVARCHAR(254) NOT NULL UNIQUE, StatusKey NVARCHAR(40) NOT NULL, Progress INT NOT NULL DEFAULT 0 CHECK (Progress BETWEEN 0 AND 100));
IF OBJECT_ID(N'dbo.Instructors',N'U') IS NULL
CREATE TABLE dbo.Instructors (Id INT NOT NULL PRIMARY KEY, Name NVARCHAR(120) NOT NULL, Expertise NVARCHAR(200) NULL, Email NVARCHAR(254) NULL UNIQUE);
IF OBJECT_ID(N'dbo.Courses',N'U') IS NULL
CREATE TABLE dbo.Courses (Id INT NOT NULL PRIMARY KEY, Title NVARCHAR(160) NOT NULL UNIQUE, InstructorId INT NULL REFERENCES dbo.Instructors(Id), StatusKey NVARCHAR(40) NOT NULL, Progress INT NOT NULL DEFAULT 0 CHECK (Progress BETWEEN 0 AND 100));
IF OBJECT_ID(N'dbo.Enrollments',N'U') IS NULL
CREATE TABLE dbo.Enrollments (Id INT NOT NULL PRIMARY KEY, StudentId INT NOT NULL REFERENCES dbo.Students(Id), CourseId INT NOT NULL REFERENCES dbo.Courses(Id), EnrolledAt DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME(), StatusKey NVARCHAR(40) NOT NULL, CONSTRAINT UQ_Enrollment_StudentCourse UNIQUE(StudentId,CourseId));
IF OBJECT_ID(N'dbo.Attendance',N'U') IS NULL
CREATE TABLE dbo.Attendance (Id INT NOT NULL PRIMARY KEY, EnrollmentId INT NOT NULL REFERENCES dbo.Enrollments(Id), SessionDate DATE NOT NULL, StatusKey NVARCHAR(40) NOT NULL, CONSTRAINT UQ_Attendance_EnrollmentDate UNIQUE(EnrollmentId,SessionDate));
IF OBJECT_ID(N'dbo.Assignments',N'U') IS NULL
CREATE TABLE dbo.Assignments (Id INT NOT NULL PRIMARY KEY, CourseId INT NOT NULL REFERENCES dbo.Courses(Id), Title NVARCHAR(200) NOT NULL, DueDate DATETIME2 NOT NULL, StatusKey NVARCHAR(40) NOT NULL);
IF OBJECT_ID(N'dbo.Exams',N'U') IS NULL
CREATE TABLE dbo.Exams (Id INT NOT NULL PRIMARY KEY, CourseId INT NOT NULL REFERENCES dbo.Courses(Id), Title NVARCHAR(200) NOT NULL, ExamDate DATETIME2 NOT NULL, Questions INT NOT NULL CHECK (Questions >= 0), StatusKey NVARCHAR(40) NOT NULL);
IF OBJECT_ID(N'dbo.Grades',N'U') IS NULL
CREATE TABLE dbo.Grades (Id INT NOT NULL PRIMARY KEY, EnrollmentId INT NOT NULL REFERENCES dbo.Enrollments(Id), Score DECIMAL(5,2) NOT NULL CHECK (Score BETWEEN 0 AND 100), Letter NVARCHAR(5) NULL);
IF OBJECT_ID(N'dbo.Certificates',N'U') IS NULL
CREATE TABLE dbo.Certificates (Id INT NOT NULL PRIMARY KEY, EnrollmentId INT NOT NULL REFERENCES dbo.Enrollments(Id), IssuedAt DATETIME2 NOT NULL, Code NVARCHAR(80) NOT NULL UNIQUE);
IF OBJECT_ID(N'dbo.AuditLog',N'U') IS NULL
CREATE TABLE dbo.AuditLog (Id BIGINT IDENTITY(1,1) PRIMARY KEY, OccurredAt DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME(), UserName NVARCHAR(120) NOT NULL, ActionKey NVARCHAR(80) NOT NULL, Entity NVARCHAR(250) NOT NULL);
GO
